impl<'a> OptNode for Opt0<'a> {
    type Inner = Token;
    fn value(&self) -> Option<&Self::Inner> {
        match self {
            Opt0::Alt0 { lit_0, .. } => Some(lit_0),
            Opt0::Alt1 { .. } => None,
            Opt0::Amb(_) => panic!("unexpected ambiguity in optional node"),
        }
    }
}
